ST.xhtml:
// ============================================================
// Tc2_Standard.stLibVersion_Tc2_Standard 演示程序
// ============================================================
// 注意：本程序需要项目同时引用 Tc2_System（提供 ST_LibVersion 类型与 F_CmpLibVersion）
// 验证步骤：
//   1. 在 References 中确认引用了 Tc2_Standard 与 Tc2_System
//   2. 编译并登录目标
//   3. 在线监视 stMyVer 应显示 1.3.4 或更高
//   4. 在线监视 bOk 应为 TRUE
//   5. 把 iMinor := 99 临时改大，重新登录 → bOk 应变 FALSE
// ============================================================

stMyVer := stLibVersion_Tc2_Standard;

bOk := F_CmpLibVersion(
    stLibVersion := stLibVersion_Tc2_Standard,
    iMajor       := 1,
    iMinor       := 3,
    iBuild       := 4,
    iRevision    := 0,
    nCmpType     := E_CmpLibVersion.GreaterOrEqual
);
